// K16.5 — fonte semanal compartilhada. O estado operacional legado é preservado.
let qoeWeeklyDataK165=null,qoeWeeklyBusyK165=false,qoeWeeklyErrorK165='';
function qoeWeeklyEscapeK165(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function qoeWeeklyApplyK165(data){
 if(data?.versao!==165||!Number.isInteger(data.semana_atual)||!Array.isArray(data.semanas)||!data.semanas.some(w=>w.semana===data.semana_atual))throw Error('Resposta semanal inválida.');
 if(qoeWeeklyDataK165&&(data.semana_atual<qoeWeeklyDataK165.semana_atual||Date.parse(data.atualizado_em)<Date.parse(qoeWeeklyDataK165.atualizado_em)))return;
 if(!localStorage.getItem(STATEKEY+'_antes_k165'))localStorage.setItem(STATEKEY+'_antes_k165',JSON.stringify(state));
 qoeWeeklyDataK165=data;qoeWeeklyErrorK165='';state.currentWeek=data.semana_atual;
 state.distributed=state.distributed||{};
 data.semanas.forEach(w=>{
   // Preserva marcações locais anteriores no backup. A nova marcação é compartilhada.
   Object.keys(state.distributed).filter(k=>k.startsWith(w.semana+'|')).forEach(k=>delete state.distributed[k]);
   Object.entries(w.distribuidas||{}).forEach(([t,d])=>{state.distributed[w.semana+'|'+t]=d;});
 });
 persist();renderWeeks();renderTechCards();
}
async function qoeWeeklyLoadK165(){
 if(!await qoeCheckSession()){
   qoeWeeklyDataK165=null;qoeWeeklyErrorK165='Entre na Gestão para consultar o controle semanal compartilhado.';renderWeeks();return false;
 }
 try{
   let {data,error}=await qoeRpc('gestao_semanal_ler');
   if(error)throw error;
   if(data.importacao_distribuicao_pendente&&Object.keys(state.distributed||{}).some(k=>k.startsWith('1|'))){
     const imported=await qoeRpc('gestao_semanal_importar_distribuicao',{p_marcacoes:state.distributed});
     if(imported.error)throw imported.error;data=imported.data;
   }
   qoeWeeklyApplyK165(data);return true;
 }catch(e){
   qoeWeeklyErrorK165='Controle semanal indisponível. Confira a instalação do SQL K16.5 e atualize do Supabase. '+(e.message||e);
   renderWeeks();return false;
 }
}
function qoeWeeklySelectedK165(){
 if(!qoeWeeklyDataK165)return null;
 const n=Number(document.getElementById('weekSel')?.value)||qoeWeeklyDataK165.semana_atual;
 return qoeWeeklyDataK165.semanas.find(w=>w.semana===n)||qoeWeeklyDataK165.semanas.find(w=>w.semana===qoeWeeklyDataK165.semana_atual);
}
function qoeWeeklyTotalsK165(w){
 if(!w)return null;
 const x={week:w.semana,sent:0,done:0,normalized:0,pending:0,newPorts:0,withdrawn:0,unknown:0,active:0,totalTechs:w.tecnicos.length,rate:0};
 w.tecnicos.forEach(t=>{
   x.sent+=t.recebidas;x.done+=t.tratadas;x.normalized+=t.normalizadas;
   x.pending+=t.pendentes;x.newPorts+=t.novas;x.withdrawn+=t.retiradas;x.unknown+=t.sem_leitura;
   if(t.tratadas>0)x.active++;
 });
 x.rate=x.sent?100*x.done/x.sent:0;return x;
}

const sel=document.getElementById('weekSel'),body=document.getElementById('weeklyBody');
if(!sel||!body)return;
if(!qoeWeeklyDataK165){body.innerHTML='<tr><td colspan="8">'+qoeWeeklyEscapeK165(qoeWeeklyErrorK165||'Conecte ao Supabase para carregar as semanas.')+'</td></tr>';}
else{
  const previous=Number(sel.value)||qoeWeeklyDataK165.semana_atual;
  sel.innerHTML=qoeWeeklyDataK165.semanas.map(w=>`<option value="${w.semana}">Semana ${w.semana}${w.fechada_em?' — encerrada':' — atual'}</option>`).join('');
  sel.value=String(qoeWeeklyDataK165.semanas.some(w=>w.semana===previous)?previous:qoeWeeklyDataK165.semana_atual);
  const w=qoeWeeklySelectedK165();
  body.innerHTML=w.tecnicos.map(t=>{
    const dist=w.distribuidas?.[t.tecnico];
    return `<tr><td><b>${qoeWeeklyEscapeK165(t.tecnico)}</b></td><td>Semana ${w.semana}</td><td>${t.recebidas}</td><td>${t.tratadas}</td><td>${t.normalizadas}</td><td>${t.pendentes}</td><td>${t.novas}</td><td>${dist?'<span class="distbadge">DISTRIBUÍDA ✓ '+qoeWeeklyEscapeK165(dist.date)+' '+qoeWeeklyEscapeK165(dist.time)+'</span>':'<span class="sub">Não distribuída</span>'}</td></tr>`;
  }).join('');

const note=document.getElementById('weeklySyncK165');
if(note){
  const w=qoeWeeklySelectedK165();
  note.textContent=qoeWeeklyErrorK165|| (w?'Semana '+w.semana+' • início '+w.inicio.split('-').reverse().join('/')+(w.fim?' • fim '+w.fim.split('-').reverse().join('/'):'')+' • dados compartilhados no Supabase.':'');
  if(w?.demandas_apos_corte)note.textContent+=' '+w.demandas_apos_corte+' demanda(s) com semana de origem anterior e recebimento após o corte foram preservadas na semana seguinte.';
}
if(typeof window.renderWeeklyV796==='function')window.renderWeeklyV796();

async function newWeek(){
 if(qoeWeeklyBusyK165)return;
 qoeWeeklyBusyK165=true;
 try{
   if(!await qoeWeeklyLoadK165())return alert(qoeWeeklyErrorK165);
   const n=qoeWeeklyDataK165.semana_atual;
   const input=prompt('Data de início da Semana '+(n+1)+' (DD/MM/AAAA):',n===1?'19/10/2026':new Date().toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'}));
   if(input===null)return;
   const m=/^(\d{2})\/(\d{2})\/(\d{4})$/.exec(input.trim());
   const date=m?new Date(+m[3],+m[2]-1,+m[1]):null;
   if(!date||date.getDate()!==+m[1]||date.getMonth()!==+m[2]-1||date.getFullYear()!==+m[3])return alert('Informe uma data válida no formato DD/MM/AAAA.');
   if(!confirm('Fechar a Semana '+n+' e abrir a Semana '+(n+1)+' em '+input.trim()+'? O histórico será preservado. Somente pendências serão carregadas; novas portas dependem de distribuição manual.'))return;
   const {data,error}=await qoeRpc('gestao_semanal_iniciar',{p_semana_atual:n,p_inicio:m[3]+'-'+m[2]+'-'+m[1]});
   if(error)throw error;
   qoeWeeklyApplyK165(data);
   document.getElementById('weekSel').value=String(data.semana_atual);renderWeeks();
   alert('Semana '+data.semana_atual+' aberta no Supabase. Atualize a Gestão no outro computador para conferir.');
 }catch(e){alert('Não foi possível confirmar a abertura. Atualize do Supabase antes de tentar novamente. '+(e.message||e));}
 finally{qoeWeeklyBusyK165=false;}
}

async function toggleDistributed(tech){
 if(!await qoeWeeklyLoadK165())return alert(qoeWeeklyErrorK165);
 const n=qoeWeeklyDataK165.semana_atual;
 const w=qoeWeeklyDataK165.semanas.find(w=>w.semana===n);
 const mark=!w.distribuidas?.[tech];
 if(!mark&&!confirm('Remover a marcação de lista distribuída para '+tech+'?'))return;
 const {data,error}=await qoeRpc('gestao_semanal_distribuida',{p_tecnico:tech,p_semana_esperada:n,p_distribuida:mark});
 if(error)return alert('Marcação não confirmada: '+error.message);
 qoeWeeklyApplyK165(data);

const w=qoeWeeklyDataK165.semanas.find(w=>w.semana===qoeWeeklyDataK165.semana_atual);
const m=w.tecnicos.find(x=>x.tecnico===t)||{recebidas:0,tratadas:0,normalizadas:0,pendentes:0,novas:0};
out+='\nSemana '+w.semana+'\n';
out+='Portas recebidas: '+m.recebidas+'\n';
out+='Portas tratadas: '+m.tratadas+'\n';
out+='Normalizadas sem atuação: '+m.normalizadas+'\n';
out+='Portas pendentes: '+m.pendentes+'\n';
out+='Novas nesta semana: '+m.novas+'\n\n';

const p=target,t=techSel.value;
if(!p||!t)return alert('Selecione a porta e o técnico.');
if(window.__qoeAllocBusyK165)return;
window.__qoeAllocBusyK165=true;
try{
  if(!await qoeWeeklyLoadK165())return alert(qoeWeeklyErrorK165);
  const {error}=await qoeRpc('gestao_semanal_alocar',{p_porta:p,p_tecnico:t,p_semana_esperada:qoeWeeklyDataK165.semana_atual});
  if(error)return alert('Alocação não confirmada no Supabase: '+error.message);
  _qoeConfirmAlloc();await qoeRemoteRefresh();
}finally{window.__qoeAllocBusyK165=false;}

if(!x){['wkSent','wkDone','wkPending','wkRate','wkTech'].forEach(id=>document.getElementById(id).textContent='—');wkReading.textContent=qoeWeeklyErrorK165||'Conecte ao Supabase para carregar o resumo semanal.';return;}
wkSent.textContent=x.sent;wkDone.textContent=x.done;if(document.getElementById('wkNormalized'))wkNormalized.textContent=x.normalized||0;wkPending.textContent=x.pending;wkRate.textContent=pct(x.rate);wkTech.textContent=x.active+' de '+x.totalTechs;
wkReading.innerHTML=`Semana ${x.week}. Foram tratadas <b>${x.done} de ${x.sent} portas (${pct(x.rate)})</b>. <b>${x.normalized||0}</b> normalizaram sem atuação e não contam como produtividade. Permanecem <b>${x.pending} portas pendentes</b>. Dos ${x.totalTechs} técnicos, <b>${x.active} registraram devolutivas</b> na semana. Retiradas: ${x.withdrawn}. Sem leitura disponível: ${x.unknown}. Portas que retornaram ao tratamento podem constar em tratadas e pendentes.`;

   if(!await qoeWeeklyLoadK165())return alert(qoeWeeklyErrorK165);
   const x=calc();if(!x)return;
   const msg=`QOE HFC — SEMANA ${x.week}

Portas enviadas: ${x.sent}
Portas tratadas: ${x.done}
Normalizadas sem atuação: ${x.normalized||0}
Portas pendentes: ${x.pending}
Novas nesta semana: ${x.newPorts}
Retiradas: ${x.withdrawn}
Execução da semana: ${pct(x.rate)}
Técnicos com devolutivas: ${x.active} de ${x.totalTechs}

